CREATE TABLE screening_project_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES screening_project_versions(id) DEFERRABLE INITIALLY DEFERRED,store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('record','withdraw')),title TEXT NOT NULL,institution TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),activity_note TEXT NOT NULL,authorization_status TEXT NOT NULL CHECK(authorization_status IN('unknown','recorded','refused')),authorization_reference TEXT,authorization_note TEXT NOT NULL,record_reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence));
CREATE VIEW screening_project_current AS SELECT v.* FROM screening_project_versions v WHERE revision=(SELECT max(revision) FROM screening_project_versions WHERE root_id=v.root_id);
CREATE TRIGGER screening_project_source BEFORE INSERT ON screening_project_versions BEGIN
 SELECT CASE WHEN NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM screening_project_versions WHERE store_id=NEW.store_id),1) OR NEW.revision=1 AND (NEW.root_id<>NEW.id OR NEW.action<>'record') OR NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM screening_project_current p WHERE p.root_id=NEW.root_id AND p.store_id=NEW.store_id AND p.revision+1=NEW.revision AND (NEW.action='record' OR p.action='record')) THEN RAISE(ABORT,'screening project fixed store/root continuous version') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception','professional') AND coalesce(s.must_change_password,0)=0 AND (u.role='manager' OR NEW.revision=1 AND NEW.owner_id=u.id OR NEW.revision>1 AND EXISTS(SELECT 1 FROM screening_project_current p WHERE p.root_id=NEW.root_id AND p.owner_id=u.id AND NEW.owner_id=p.owner_id))) THEN RAISE(ABORT,'screening project current responsible staff') END;
 SELECT CASE WHEN NEW.action='record' AND NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.owner_id AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception','professional') AND coalesce(s.must_change_password,0)=0) THEN RAISE(ABORT,'screening project explicit eligible preparation owner') END;
 SELECT CASE WHEN NEW.action='withdraw' AND NOT EXISTS(SELECT 1 FROM screening_project_current p WHERE p.root_id=NEW.root_id AND p.action='record' AND NEW.title=p.title AND NEW.institution=p.institution AND NEW.owner_id=p.owner_id AND NEW.activity_note=p.activity_note AND NEW.authorization_status=p.authorization_status AND NEW.authorization_reference IS p.authorization_reference AND NEW.authorization_note=p.authorization_note) THEN RAISE(ABORT,'screening project withdraw preserves old source facts') END;
END;
CREATE TRIGGER screening_project_text BEFORE INSERT ON screening_project_versions WHEN length(trim(NEW.title)) NOT BETWEEN 1 AND 160 OR length(NEW.title)>160 OR instr(NEW.title,char(0))>0 OR length(trim(NEW.institution)) NOT BETWEEN 1 AND 160 OR length(NEW.institution)>160 OR instr(NEW.institution,char(0))>0 OR length(trim(NEW.activity_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.activity_note)>2000 OR instr(NEW.activity_note,char(0))>0 OR length(trim(NEW.authorization_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.authorization_note)>2000 OR instr(NEW.authorization_note,char(0))>0 OR length(trim(NEW.record_reason)) NOT BETWEEN 1 AND 300 OR length(NEW.record_reason)>300 OR instr(NEW.record_reason,char(0))>0 OR NEW.authorization_status='unknown' AND NEW.authorization_reference IS NOT NULL OR NEW.authorization_status<>'unknown' AND (NEW.authorization_reference IS NULL OR length(trim(NEW.authorization_reference)) NOT BETWEEN 1 AND 500 OR length(NEW.authorization_reference)>500 OR instr(NEW.authorization_reference,char(0))>0) BEGIN SELECT RAISE(ABORT,'screening project explicit source facts');END;
CREATE TRIGGER screening_project_time BEFORE INSERT ON screening_project_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM screening_project_versions WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'screening project canonical nondecreasing time');END;
CREATE TRIGGER screening_project_no_update BEFORE UPDATE ON screening_project_versions BEGIN SELECT RAISE(ABORT,'screening project immutable version');END;
CREATE TRIGGER screening_project_no_delete BEFORE DELETE ON screening_project_versions BEGIN SELECT RAISE(ABORT,'screening project immutable version');END;
